<x-app-layout><x-slot name="header"><h2 class="font-semibold text-xl">Alarms</h2></x-slot><div class="p-6"><div id="alarms" class="space-y-2"></div></div><script>fetch('/api/live').then(r=>r.json()).then(d=>{document.querySelector('#alarms').innerHTML=(d.active_alarms||[]).map(a=>`<div class="bg-white p-3 rounded"><b>${a.priority}</b> ${a.message}<br><small>${a.action}</small></div>`).join('')||'<div>No active advisory alarms</div>'})</script></x-app-layout>
